-- HireSwift initial Supabase schema. Apply in the target project before enabling persistence.
create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', company_name text not null default '', created_at timestamptz not null default now());
create table if not exists public.jobs (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, title text not null, company text not null default '', description text not null default '', required_skills text[] not null default '{}', preferred_skills text[] not null default '{}', min_experience numeric not null default 0, education text not null default '', min_cgpa numeric not null default 0, location text not null default '', employment_type text not null default 'Full-time', status text not null default 'Active' check(status in ('Active','Closed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.candidates (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, full_name text not null default '', email text not null default '', phone text not null default '', location text not null default '', education text not null default '', tenth_percentage numeric, twelfth_percentage numeric, cgpa numeric, graduation_year integer, technical_skills text[] not null default '{}', programming_languages text[] not null default '{}', technologies text[] not null default '{}', projects text[] not null default '{}', experience_years numeric not null default 0, certifications text[] not null default '{}', source text not null default 'Recruiter-entered', manual_review_required boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(owner_id,email));
create table if not exists public.candidate_skills (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, candidate_id uuid not null references public.candidates(id) on delete cascade, skill text not null, category text not null default 'technical', unique(candidate_id,skill,category));
create table if not exists public.applications (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, candidate_id uuid not null references public.candidates(id) on delete cascade, job_id uuid not null references public.jobs(id) on delete cascade, stage text not null default 'Applied' check(stage in ('Applied','Shortlisted','Interview','Offer','Rejected')), match_score integer check(match_score between 0 and 100), interview_date timestamptz, interview_notes text not null default '', recruiter_feedback text not null default '', rejection_reason text not null default '', offer_status text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(candidate_id,job_id));
create table if not exists public.resumes (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, candidate_id uuid references public.candidates(id) on delete set null, storage_path text not null, file_name text not null, mime_type text not null check(mime_type in ('application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document')), parsed_fields jsonb not null default '{}', review_required boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.interviews (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, application_id uuid not null references public.applications(id) on delete cascade, scheduled_at timestamptz, notes text not null default '', feedback text not null default '', created_at timestamptz not null default now());
create table if not exists public.recruitment_activities (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, candidate_id uuid references public.candidates(id) on delete set null, application_id uuid references public.applications(id) on delete set null, action text not null, details jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists public.email_logs (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, subject text not null, recipients text[] not null default '{}', body text not null default '', status text not null default 'draft' check(status in ('draft','sent','failed')), provider_message_id text, created_at timestamptz not null default now());
-- Owner isolation applies consistently to every workspace table.
do $$ declare t text; begin foreach t in array array['profiles','jobs','candidates','candidate_skills','applications','resumes','interviews','recruitment_activities','email_logs'] loop execute format('alter table public.%I enable row level security',t); if t='profiles' then execute format('create policy %I on public.%I for all using (id = auth.uid()) with check (id = auth.uid())','owner_all_'||t,t); else execute format('create policy %I on public.%I for all using (owner_id = auth.uid()) with check (owner_id = auth.uid())','owner_all_'||t,t); end if; end loop; end $$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('private-resumes','private-resumes',false,10485760,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document']) on conflict(id) do nothing;
create policy "Recruiters access own resume files" on storage.objects for all using (bucket_id='private-resumes' and (storage.foldername(name))[1]=auth.uid()::text) with check (bucket_id='private-resumes' and (storage.foldername(name))[1]=auth.uid()::text);
